SET local check_function_bodies = off;

CREATE TABLE "insite"."markouts" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"          bigint                   NOT NULL,
  "details"         jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "submitted_by"    text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "idempotency_key" uuid,
  CONSTRAINT "markouts_idempotency_key_key" UNIQUE (idempotency_key),
  CONSTRAINT "markouts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "insite"."markouts"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."job_attachments"
  ADD COLUMN "markout_id" bigint;

CREATE OR REPLACE FUNCTION insite.submit_install_report (
  p_job_id          bigint,
  p_details         jsonb,
  p_submitted_by    text,
  p_idempotency_key uuid,
  p_attachments     jsonb
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
DECLARE
  v_report_id bigint;
  v_attachment jsonb;
BEGIN
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Idempotency key is required'
      USING ERRCODE = '22023';
  END IF;

  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'Job ID is required'
      USING ERRCODE = '22023';
  END IF;

  IF p_details IS NULL OR jsonb_typeof(p_details) <> 'object' THEN
    RAISE EXCEPTION 'Report details must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF p_attachments IS NOT NULL
     AND jsonb_typeof(p_attachments) <> 'array' THEN
    RAISE EXCEPTION 'Attachments must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF p_attachments IS NOT NULL THEN
    FOR v_attachment IN
      SELECT value
      FROM jsonb_array_elements(p_attachments)
    LOOP
      IF jsonb_typeof(v_attachment) <> 'object'
         OR NULLIF(v_attachment->>'file_name', '') IS NULL
         OR NULLIF(v_attachment->>'file_path', '') IS NULL
         OR NULLIF(v_attachment->>'file_type', '') IS NULL
         OR NULLIF(v_attachment->>'category', '') IS NULL
         OR NULLIF(v_attachment->>'file_tag', '') IS NULL
         OR NULLIF(v_attachment->>'file_size', '') IS NULL
      THEN
        RAISE EXCEPTION 'Each attachment must contain file_name, file_path, file_type, file_size, category, and file_tag'
          USING ERRCODE = '22023';
      END IF;

      IF (v_attachment->>'file_size') !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'Attachment file_size must be a non-negative integer'
          USING ERRCODE = '22023';
      END IF;
    END LOOP;
  END IF;

   INSERT INTO insite.install_reports (
    job_id,
    details,
    submitted_by,
    idempotency_key
  )
  VALUES (
    p_job_id,
    p_details,
    p_submitted_by,
    p_idempotency_key
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_report_id;

  IF v_report_id IS NULL THEN
    SELECT id
    INTO v_report_id
    FROM insite.install_reports
    WHERE idempotency_key = p_idempotency_key;

    IF v_report_id IS NULL THEN
      RAISE EXCEPTION 'Unable to resolve existing install report for idempotency key'
        USING ERRCODE = '40001';
    END IF;
  ELSE
    IF p_attachments IS NOT NULL THEN
      FOR v_attachment IN
        SELECT value
        FROM jsonb_array_elements(p_attachments)
      LOOP
        INSERT INTO public.job_attachments (
          job_id,
          install_report_id,
          file_name,
          file_path,
          file_type,
          file_size,
          category,
          file_tag,
          uploaded_by
        )
        VALUES (
          p_job_id,
          v_report_id,
          v_attachment->>'file_name',
          v_attachment->>'file_path',
          v_attachment->>'file_type',
          (v_attachment->>'file_size')::bigint,
          v_attachment->>'category',
          v_attachment->>'file_tag',
          p_submitted_by
        );
      END LOOP;
    END IF;
  END IF;

  UPDATE public.installation AS i
SET installation_report_received = NOW()
FROM public.jobs AS j
WHERE j.id = p_job_id
  AND i.installation_id = j.installation_id
  AND i.installation_report_received IS NULL;

IF NOT FOUND THEN
  IF NOT EXISTS (
    SELECT 1
    FROM public.jobs AS j
    JOIN public.installation AS i
      ON i.installation_id = j.installation_id
    WHERE j.id = p_job_id
      AND i.installation_report_received IS NULL
  ) THEN
    NULL;
  ELSE
    RAISE EXCEPTION
      'Failed to update installation_report_received for job %',
      p_job_id;
  END IF;
END IF;

  RETURN v_report_id;
END;
$function$;

CREATE OR REPLACE FUNCTION insite.submit_markout (
  p_job_id          bigint,
  p_details         jsonb,
  p_submitted_by    text,
  p_idempotency_key uuid,
  p_attachments     jsonb
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
DECLARE
  v_markout_id bigint;
  v_attachment jsonb;
BEGIN
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Idempotency key is required'
      USING ERRCODE = '22023';
  END IF;

  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'Job ID is required'
      USING ERRCODE = '22023';
  END IF;

  IF p_details IS NULL OR jsonb_typeof(p_details) <> 'object' THEN
    RAISE EXCEPTION 'Markout details must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF p_attachments IS NOT NULL
     AND jsonb_typeof(p_attachments) <> 'array' THEN
    RAISE EXCEPTION 'Attachments must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  IF p_attachments IS NOT NULL THEN
    FOR v_attachment IN
      SELECT value
      FROM jsonb_array_elements(p_attachments)
    LOOP
      IF jsonb_typeof(v_attachment) <> 'object'
         OR NULLIF(v_attachment->>'file_name', '') IS NULL
         OR NULLIF(v_attachment->>'file_path', '') IS NULL
         OR NULLIF(v_attachment->>'file_type', '') IS NULL
         OR NULLIF(v_attachment->>'category', '') IS NULL
         OR NULLIF(v_attachment->>'file_size', '') IS NULL
      THEN
        RAISE EXCEPTION 'Each attachment must contain file_name, file_path, file_type, file_size, and category'
          USING ERRCODE = '22023';
      END IF;

      IF (v_attachment->>'file_size') !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'Attachment file_size must be a non-negative integer'
          USING ERRCODE = '22023';
      END IF;
    END LOOP;
  END IF;

  INSERT INTO insite.markouts (
    job_id,
    details,
    submitted_by,
    idempotency_key
  )
  VALUES (
    p_job_id,
    p_details,
    p_submitted_by,
    p_idempotency_key
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_markout_id;

  IF v_markout_id IS NULL THEN
    SELECT id
    INTO v_markout_id
    FROM insite.markouts
    WHERE idempotency_key = p_idempotency_key;

    IF v_markout_id IS NULL THEN
      RAISE EXCEPTION 'Unable to resolve existing markout for idempotency key'
        USING ERRCODE = '40001';
    END IF;
  ELSE
    IF p_attachments IS NOT NULL THEN
      FOR v_attachment IN
        SELECT value
        FROM jsonb_array_elements(p_attachments)
      LOOP
        INSERT INTO public.job_attachments (
          job_id,
          markout_id,
          file_name,
          file_path,
          file_type,
          file_size,
          category,
          file_tag,
          uploaded_by
        )
        VALUES (
          p_job_id,
          v_markout_id,
          v_attachment->>'file_name',
          v_attachment->>'file_path',
          v_attachment->>'file_type',
          (v_attachment->>'file_size')::bigint,
          v_attachment->>'category',
          COALESCE(v_attachment->>'file_tag', 'Markout'),
          p_submitted_by
        );
      END LOOP;
    END IF;
  END IF;

  RETURN v_markout_id;
END;
$function$;

CREATE OR REPLACE FUNCTION insite.update_markout (
  p_markout_id             bigint,
  p_details                jsonb,
  p_deleted_attachment_ids bigint[],
  p_new_attachments        jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
DECLARE
  v_job_id bigint;
  v_attachment jsonb;
BEGIN
  SELECT job_id INTO v_job_id
  FROM insite.markouts
  WHERE id = p_markout_id;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'Markout not found' USING ERRCODE = '22023';
  END IF;

  UPDATE insite.markouts
  SET details = p_details,
      updated_at = now()
  WHERE id = p_markout_id;

  IF p_deleted_attachment_ids IS NOT NULL AND array_length(p_deleted_attachment_ids, 1) > 0 THEN
    DELETE FROM public.job_attachments
    WHERE id = ANY(p_deleted_attachment_ids)
      AND markout_id = p_markout_id;
  END IF;

  IF p_new_attachments IS NOT NULL AND jsonb_array_length(p_new_attachments) > 0 THEN
    FOR v_attachment IN SELECT * FROM jsonb_array_elements(p_new_attachments)
    LOOP
      INSERT INTO public.job_attachments (
        job_id,
        markout_id,
        file_name,
        file_path,
        file_type,
        file_size,
        category,
        file_tag,
        uploaded_by
      )
      VALUES (
        v_job_id,
        p_markout_id,
        v_attachment->>'file_name',
        v_attachment->>'file_path',
        v_attachment->>'file_type',
        (v_attachment->>'file_size')::bigint,
        v_attachment->>'category',
        COALESCE(v_attachment->>'file_tag', 'Markout'),
        v_attachment->>'uploaded_by'
      );
    END LOOP;
  END IF;
END;
$function$;

ALTER TABLE "insite"."markouts"
  ADD CONSTRAINT "markouts_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE;

ALTER TABLE "public"."job_attachments"
  ADD CONSTRAINT "job_attachments_markout_id_fkey" FOREIGN KEY (markout_id) REFERENCES insite.markouts(id) ON DELETE CASCADE;

CREATE INDEX idx_markouts_details_gin ON insite.markouts USING gin (details);

CREATE INDEX idx_markouts_job_id ON insite.markouts USING btree (job_id);

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON insite.markouts
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable insert for authenticated users" ON "insite"."markouts"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable read access for authenticated users" ON "insite"."markouts"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for authenticated users" ON "insite"."markouts"
  FOR UPDATE
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text))
  WITH CHECK ((auth.role() = 'authenticated'::text));

REVOKE ALL ON FUNCTION "insite"."submit_markout"(bigint, jsonb, text, uuid, jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "insite"."submit_markout"(bigint, jsonb, text, uuid, jsonb) TO "authenticated";

REVOKE ALL ON FUNCTION "insite"."update_markout"(bigint, jsonb, bigint[], jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "insite"."update_markout"(bigint, jsonb, bigint[], jsonb) TO "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "insite"."markouts" TO "anon", "authenticated", "service_role";
